import { expect, expectStatus, test, uniqueName, type Document } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ name: uniqueName("Expired COI") });

  // The factory has no expired sample, so the certificate is uploaded inline with yesterday's date.
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = Buffer.from(
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1291\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`,
  );
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: { name: "insurance_certificate_expired.txt", mimeType: "text/plain", buffer: certificate },
    },
  });
  const insuranceDoc = await expectStatus<Document>(upload, 201);

  let documents: Document[] = [];
  await expect
    .poll(
      async () => {
        documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);

  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const extraction = await factory.extraction(insuranceDoc.id, "reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  // Per the scenario's IMPORTANT note, the exact status and error code are not checked; only that the server does not fail.
  const status = response.status();
  expect(status, await response.text()).toBeLessThan(500);
});
